//HOW TO MAKE A MUFFIN CAKE FOR BEGINNERS
#include <iostream>
using namespace std;
int main() {
    cout << "Yield: 12 muffins\n";
    cout << "Oven temperature : 190 degrees Celsius/375 degrees Fahrenheit\n" << endl;
    cout << "A. INGREDIENTS\n";
    cout << "- All-purpose flour: 250g (2 cups)\n";
    cout << "- Granulated sugar: 150g (3/4 cup)\n";
    cout << "- Baking powder: 10g (2 teaspoons)\n";
    cout << "- Salt: 1/4 teaspoon\n";
    cout << "- Eggs (room temperature): 2\n";
    cout << "- Milk: 180ml (3/4 cup)\n";
    cout << "- Neutral oil (or melted, cooled butter): 80ml (1/3 cup)\n";
    cout << "- Vanilla extract: 1 teaspoon\n";
    cout << "- Blue berries (fresh or frozen): 150-180g (1-1.25 cups)\n";
    cout << "- (Optional) Finely grated lemon zest: 1 teaspoon\n" << endl;

    cout << "B. TOOLS\n";
    cout << "- Oven; center rack; oven mitts\n";
    cout << "- 12-cup muffin tin; paper liners (or nonstick + pastry brush)\n";
    cout << "- 2 mixing bowls(dry/wet), whisk, spatula\n";
    cout << "- Measuring cups/spoons; kitchen scale\n";
    cout << "-Spoon or ice-cream scoop; toothpicks for doneness test\n";
    cout << "- Cooling rack; clean towel\n" << endl;

    cout << "C. STEPS (ONE ACTION PER NUMBERED PARAGRAPH)\n";
    cout << "1.Wash hands, clear the workspace, and preheat the oven to 190 °C (375 °F) for 15 minutes.\n" << "Tools: Oven, oven mitts.\n" << "Why: Stable heat ensures proper rise and texture.\n";
    cout << "2. Prepare the pan: line all 12 wells with paper liners (or brush a thin layer of oil/butter if not using liners).\n" << "Tools: Muffin pan, liners/brush.\n" << "Ingredients: a little oil/butter (if no liners).\n";
    cout << "3.Weigh/measure every ingredient in Section A; bring eggs and milk to room temperature.\n" << "Tools: scale, measuring cups/spoons.\n" << "Tip: If milk is cold, leave it out 10–15 minutes.\n";
    cout << "4.Mix dry ingredients: in Bowl 1, add flour, sugar, baking powder, and salt; whisk 15–20 seconds to combine.\n" << "Tools: Bowl 1, whisk.\n" << "Ingredients: flour, sugar, baking powder, salt.\n";
    cout << "5.Mix wet ingredients: in Bowl 2, lightly beat eggs, then add milk, oil (or cooled melted butter), vanilla (and lemon zest if using) until homogeneous.\n" << "Tools: Bowl 2, whisk.\n" << "Ingredients: eggs, milk, oil/butter, vanilla (and lemon zest if using).\n";
    cout << "6. Combine wet and dry: pour the dry mix into the wet; fold gently with a spatula just until barely combined (a few small streaks of flour are fine).\n" << "Tool: spatula.\n" << "Beginner note: Do not beat like a cake—overmixing makes muffins tough.\n";
    cout << "7. Add blueberries: sprinkle over the batter and fold 3–5 gentle strokes to distribute.\n" << "Ingredient: blueberries.\n" << "Tip: If using frozen berries, do not thaw to avoid blue batter.\n";
    cout << "8. Portion batter: fill each well about 3/4 full.\n" << "Tool: spoon/scoop.\n" << "Tip: Even portions bake evenly.\n";
    cout << "9. Bake: place the pan on the center oven rack and bake for 18–22 minutes, rotating halfway through, until golden and a toothpick inserted in the center comes out clean or with a few moist crumbs.\n" << "Tool: oven, toothpicks, timer/phone.\n" << "Note: Don't open the oven during the first 10 minutes.\n";
    cout << "10. Remove safely: wear oven mitts, pull the pan out, and transfer muffins to a cooling rack.\n" << "Tools: oven mitts, cooling rack.\n" << "Safety: Avoid touching heating elements/oven walls.\n";
    cout << "11. Release & Cool: after 5 minutes, gently remove muffins from the pan; cool completely on the rack (about 30 minutes) before storing.\n" << "Tool: cooling rack.\n" << "Why: Venting steam keeps the crust from getting soggy.\n";
    cout << "12. Clean up: turn off the oven, unplug if it’s a countertop unit, wash tools, dry the pan. Tools: dishcloth/sponge.\n" << endl;

    cout << "D. BEGINNER TIPS\n" << "-Check baking powder freshness; stale leavening = poor rise.\n" << "Level off measures when using cups; a scale is most accurate.\n" << "Melted butter must cool (lukewarm, < ~35 °C/95 °F) before mixing with eggs/milk to prevent curdling.\n" << "Stop mixing once flour disappears (no big dry patches).\n" << "Use a separate timer (phone) instead of guessing; ovens vary—start checking at 18 minutes.\n" << "If tops brown too fast, tent loosely with foil for the last 5–7 minutes.\n" << endl;

    cout << "E. Mini Glossary\n" << "Muffin pan: a metal tray with multiple round wells for muffins/cupcakes.\n" << "Liner: thin paper cup placed in each well to prevent sticking and ease removal.\n" << "Preheat: turning the oven on ahead of time so it reaches target temperature before baking.\n" <<
    "Oven: an enclosed heating appliance for baking/roasting (not a microwave).\n" << "Center rack: middle position in the oven, where heat circulation is most even.\n" << "Fold: a gentle mixing motion using a spatula to lift and turn batter without deflating it.\n" << "Toothpick test: insert a toothpick into the center; if it comes out clean or with a few moist crumbs, it’s done\n" << "Level (measure): scrape a straight edge across the top of a measuring cup/spoon to get an accurate amount.\n" << endl;
    cout << "Enjoy your first batch of muffins! If you want, I can also provide a reduced-sugar, gluten-free, or all-grams version.\n";
    return 0;


}